
import type { MoneyValue } from './MoneyValue.js';
import type { RefundAdjustmentReason } from './RefundAdjustmentReason.js';

export type RefundLineItemAdjustment = { "adjustment_type": "restocking_fee" | "withheld_amount" | "refund_adjustment" | "tax_adjustment" | (string & {}); "amount_money": MoneyValue; "applies_to": string; "reason": RefundAdjustmentReason; "refund_line_item_adjustment_id": string; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "refunded_money": { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "remaining_money": { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; };
